s": "дієслово, доконаний вид (що зробити?)", "gram": "минулий час (форма на -l): ч. р., однина"}, {"form": "plan", "lemma": "plan", "ua": "план", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "pokazat", "lemma": "pokazati", "ua": "показати", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "інфінітив без кінцевого -i: так пишуть, коли «ću / će…» стоїть після дієслова («putovat će» — подорожуватиме)"}, {"form": "joj", "lemma": "joj", "ua": "їй (займенник)", "lesson": false, "pos": "займенник «їй» — коротка форма давального від ona"}, {"form": "opatiju", "lemma": "Opatija", "ua": "Опатія (місто біля моря)", "lesson": false, "pos": "назва місця", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "krk", "lemma": "Krk", "ua": "Крк (острів)", "lesson": false, "pos": "назва місця"}, {"form": "plitvička", "lemma": "Plitvička jezera", "ua": "Плітвицькі озера (національний парк)", "lesson": false, "pos": "назва місця", "gram": "частина назви «Plitvička jezera»"}, {"form": "jezera", "lemma": "Plitvička jezera", "ua": "Плітвицькі озера (національний парк)", "lesson": false, "pos": "назва місця", "gram": "знахідний відмінок (кого? що?), множина. «Plitvička jezera» — Плітвицькі озера"}], "known_ratio": 0.842}]'::jsonb;
  v_changed int;
  v_same int;
begin
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'reading_text', r.id, r.version,
         jsonb_build_object('code', r.code, 'glossary', r.glossary, 'known_ratio', r.known_ratio),
         'reading_known_a0v4 2026-10-19: словничок і частка знайомих слів перераховано після перебудови уроків A0 за темою (curriculum_a0_v4, модулі A0.1–A0.2). Тексти й питання не змінено.'
  from public.reading_texts r
  join jsonb_to_recordset(v_data) as g(code text, glossary jsonb, known_ratio numeric) on g.code = r.code
  where r.glossary is distinct from g.glossary or r.known_ratio is distinct from g.known_ratio
  on conflict (entity_type, entity_id, version) do nothing;

  with changed as (
    update public.reading_texts r
       set glossary = g.glossary, known_ratio = g.known_ratio, version = r.version + 1
      from jsonb_to_recordset(v_data) as g(code text, glossary jsonb, known_ratio numeric)
     where g.code = r.code and (r.glossary is distinct from g.glossary or r.known_ratio is distinct from g.known_ratio)
    returning r.id, r.status
  ), logged as (
    insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
    select 'reading_text', c.id, c.status, c.status, 'auto_passed', 'script', '[]'::jsonb, 'reading_known_a0v4 2026-10-19: словничок і частка знайомих слів перераховано після перебудови уроків A0 за темою (curriculum_a0_v4, модулі A0.1–A0.2). Тексти й питання не змінено.'
    from changed c
    returning 1
  )
  select count(*) into v_changed from logged;

  select count(*) into v_same
    from public.reading_texts r
    join jsonb_to_recordset(v_data) as g(code text, glossary jsonb, known_ratio numeric) on g.code = r.code
   where r.glossary = g.glossary and r.known_ratio = g.known_ratio;
  if v_same < 2 then raise exception 'Узгоджено текстів %, очікувалось 2 (чи завантажено тексти A0, A1, A2?)', v_same; end if;
  raise notice 'Готово: частина 3 з 3 — 2 текстів відповідають урокам (змінено зараз: %)', v_changed;
end
$known$;
